using System;
using System.IO;
using System.Linq;
using SMSModForge.Rendering;
using SMSModForge.Rendering.Gpu;
using Xunit;
using Xunit.Abstractions;

namespace SMSModForge.Tests;

/// <summary>
/// The game's post-processing on the graphics card (GpuPost: Beautify's own
/// passes, generated by dxbc_to_hlsl.py, run as GamePost.BloomAndFlares runs
/// them) is the processor's: the bloom and flares target the final pass reads,
/// value for value, on the shipped room and on a frame of hot spots four times
/// white; and the preview's bytes after compose, grading and sRGB, against
/// BackdropRender.Present, at every quality's parts. Within Direct3D's
/// rounding (GpuDeviceTests). Control: the card's frame without the bloom is
/// visibly not the processor's with it.
/// <para/>
/// The half-float stores are rounded to nearest in the kernel itself: the
/// card's own f32tof16 did not (2026-11-16, the author's RTX 4070 Ti SUPER:
/// every bloom value drifted up to 1% low through the passes).
/// </summary>
public sealed class GpuPostTests
{
    private readonly ITestOutputHelper _out;
    public GpuPostTests(ITestOutputHelper o) => _out = o;

    private static GamePost.Target HotSpots()
    {
        var t = new GamePost.Target(960, 540);
        var rng = new Random(7);
        for (int i = 0; i < t.Px.Length; i += 4) { t.Px[i] = (float)rng.NextDouble() * 0.5f; t.Px[i + 1] = (float)rng.NextDouble() * 0.4f; t.Px[i + 2] = (float)rng.NextDouble() * 0.3f; t.Px[i + 3] = 1f; }
        for (int k = 0; k < 40; k++)
        {
            int cx = rng.Next(960), cy = rng.Next(540), r = rng.Next(2, 30);
            for (int y = Math.Max(0, cy - r); y < Math.Min(540, cy + r); y++)
                for (int x = Math.Max(0, cx - r); x < Math.Min(960, cx + r); x++)
                {
                    int o = (y * 960 + x) * 4;
                    t.Px[o] = 4f * (float)rng.NextDouble(); t.Px[o + 1] = 3f * (float)rng.NextDouble(); t.Px[o + 2] = 2f;
                }
        }
        return t;
    }

    private static BackdropScene Scene()
        => new(PreviewBackdrop.Load(Path.Combine(TranslationCoverageTests.EditorDir, "Resources", "Backdrops", "MyRoom")));

    [Theory]
    [InlineData("room", true)]
    [InlineData("room", false)]
    [InlineData("hot", true)]
    [InlineData("hot", false)]
    public void TheCardsBloomAndFlaresAreTheProcessors(string frameName, bool flares)
    {
        using var post = GpuPost.TryCreate();
        Assert.True(post != null, "no graphics card device: " + GpuDevice.SharedFailure);
        var frame = frameName == "room" ? BackdropRender.Scene(Scene()) : HotSpots();
        var s = new GamePost.Settings();
        var cpu = GamePost.BloomAndFlaresFast(frame, s, flares, new GamePost.Work());
        var card = post!.BloomForTests(frame, s, flares, out int w, out int h);
        Assert.Equal(cpu.W, w);
        Assert.Equal(cpu.H, h);
        int exact = 0, overRelative = 0;
        double worst = 0;
        for (int i = 0; i < card.Length; i++)
        {
            if (BitConverter.SingleToInt32Bits(card[i]) == BitConverter.SingleToInt32Bits(cpu.Px[i])) { exact++; continue; }
            double rel = Math.Abs(card[i] - cpu.Px[i]) / Math.Max(1e-3, Math.Abs(cpu.Px[i]));
            worst = Math.Max(worst, rel);
            if (rel > 0.002) overRelative++;          // two half-float steps
        }
        _out.WriteLine($"{frameName}, flares {flares}: {w}x{h}; {exact} of {card.Length} values the processor's to the bit, worst {worst:P3} relative, {overRelative} over 0.2%");
        // Direct3D's division and roots can tip a value across a half float's
        // step (measured 2026-11-16: 96-99.6% to the bit, the rest within two
        // steps); a store rounding the wrong way showed as every value up to 1%
        // low, which this catches.
        Assert.True(exact > card.Length * 0.95, $"only {exact} of {card.Length} values are the processor's");
        Assert.Equal(0, overRelative);
    }

    [Theory]
    [InlineData(true, true, true)]
    [InlineData(true, false, true)]
    [InlineData(false, false, true)]
    [InlineData(false, false, false)]
    public void TheCardsPreviewBytesAreTheProcessors(bool bloom, bool flares, bool colour)
    {
        using var post = GpuPost.TryCreate();
        Assert.True(post != null, "no graphics card device: " + GpuDevice.SharedFailure);
        var scene = Scene();
        var target = BackdropRender.Scene(scene);
        var parts = new BackdropRender.PostParts(bloom, flares, colour);
        const int N = BackdropRender.FrameSize;
        var cpu = new byte[N * N * 4];
        BackdropRender.Present(target, scene, parts, cpu, new GamePost.Work());
        var card = new byte[N * N * 4];
        post!.Present(target, scene, parts, card);
        int same = 0, overOne = 0;
        for (int i = 0; i < cpu.Length; i++)
        {
            int d = Math.Abs(cpu[i] - card[i]);
            if (d == 0) same++;
            if (d > 1) overOne++;
        }
        var noBloom = new byte[N * N * 4];
        post.Present(target, scene, new BackdropRender.PostParts(false, false, colour), noBloom);
        int controlOff = bloom ? Enumerable.Range(0, cpu.Length).Count(i => Math.Abs(cpu[i] - noBloom[i]) > 1) : -1;
        _out.WriteLine($"bloom {bloom}, flares {flares}, colour {colour}: {same} of {cpu.Length} bytes the processor's, {overOne} more than a level off; "
                       + $"the card without the bloom: {controlOff} bytes over a level from the processor's with it");
        if (bloom) Assert.True(controlOff > 1000, "control: the card's frame without the bloom passes for the processor's with it");
        Assert.True(overOne <= cpu.Length / 10000, $"the card's preview is more than a level from the processor's at {overOne} bytes");
        Assert.True(same > cpu.Length * 0.99, $"only {same} of {cpu.Length} bytes are the processor's");
    }
}
